function reachingPoints(sx, sy, tx, ty) {
  // Undo one move at a time: the larger coordinate is the one the last move increased.
  while (tx >= sx && ty >= sy) {
    if (tx === sx && ty === sy) return true;
    if (tx > ty) tx -= ty;
    else if (ty > tx) ty -= tx;
    else return false;
  }
  return false;
}

