function generate(rand, size) {
  const large = size === 'large';
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const MAX = large ? 1e9 : 60;
  const sx = int(1, large ? (rand() < 0.5 ? 1000 : 100000) : 10);
  const sy = int(1, large ? (rand() < 0.5 ? 1000 : 100000) : 10);
  if (rand() < 0.2) return [sx, sy, int(1, MAX), int(1, MAX)];
  // Apply random forward moves (a move may repeat several times) so the target is reachable.
  let x = sx, y = sy;
  const moves = int(0, large ? 10 : 5);
  for (let i = 0; i < moves; i++) {
    if (rand() < 0.5) {
      const room = Math.floor((MAX - x) / y);
      if (room > 0) x += y * int(1, rand() < 0.6 ? Math.min(room, 3) : room);
    } else {
      const room = Math.floor((MAX - y) / x);
      if (room > 0) y += x * int(1, rand() < 0.6 ? Math.min(room, 3) : room);
    }
  }
  // Sometimes nudge the target off the reachable path.
  if (rand() < 0.4) {
    const step = rand() < 0.5 ? 1 : -1;
    if (rand() < 0.5) x = Math.min(MAX, Math.max(1, x + step));
    else y = Math.min(MAX, Math.max(1, y + step));
  }
  return [sx, sy, x, y];
}
